// Off-lock frames still dispatch one answer at a time, in arrival order, so a pipelined ping reads
// session_list first; a turn does not join this chain — the lock orders turns, and a ping must not
// wait behind one.
let dispatched: Promise<void> = Promise.resolve();
ws.on('message', (frame: Buffer | string) => {
  const parsed = parseWsData(frame);
  if (parsed === null) {
    sendError(ws, ErrorCodes.INVALID_FORMAT, 'Invalid JSON');
    return;
  }
  log.info('ws', 'message received', {sessionId, type: (parsed as Record<string, unknown>).type as string});
  if (isUserMessageFrame(parsed)) {
    deps.handleMessage(ws, session, parsed, connection.signal);
    return;
  }
  dispatched = dispatched
    // One answer failing must not skip the frames queued behind it.
    .catch(() => undefined)
    .then(() => deps.handleMessage(ws, session, parsed, connection.signal))
    .catch(() => undefined);
});

